public class BohrModelCalculator {
    public static void main(String[] args) {
        // Rydberg constant in m^-1
        double R = 1.097e7;

        // Principal quantum numbers
        int n1 = 100;
        int n2 = 99;

        // Calculate the wavelength
        double wavelength = 1 / (R * (1/n1/n1 - 1/n2/n2));

        // Convert to cm
        wavelength *= 100;

        // Display the result
        System.out.println("The wavelength of the transition from n=100 to n=99 is approximately " + wavelength + " cm.");
    }
}
```

